"""Unit and integration tests; no dependencies beyond the standard library."""

import array
from fractions import Fraction
import math
from pathlib import Path
import struct
import subprocess
import sys
import tempfile
import unittest
import wave

from metronome import generate_track, parse_int_list, write_midi, write_wav


def midi_messages(data: bytes):
    """Parse the explicit-status, type-0 MIDI messages generated by the library."""
    assert data[:4] == b"MThd"
    assert struct.unpack(">IHHH", data[4:14]) == (6, 0, 1, 960)
    assert data[14:18] == b"MTrk"
    length = int.from_bytes(data[18:22], "big")
    track = data[22:22 + length]
    pos = tick = 0
    output = []
    while pos < len(track):
        delta = 0
        while True:
            byte = track[pos]
            pos += 1
            delta = (delta << 7) | (byte & 127)
            if not byte & 128:
                break
        tick += delta
        status = track[pos]
        pos += 1
        if status == 0xFF:
            kind = track[pos]
            pos += 1
            size = track[pos]
            pos += 1
            payload = track[pos:pos + size]
            pos += size
            output.append((tick, "meta", kind, payload))
        elif status & 0xF0 in (0x80, 0x90):
            note, velocity = track[pos:pos + 2]
            pos += 2
            output.append((tick, status, note, velocity))
        elif status == 0xC0:
            program = track[pos]
            pos += 1
            output.append((tick, status, program, None))
        else:
            raise AssertionError(f"Unexpected status {status:x}")
    return output


class CoreTests(unittest.TestCase):
    def test_pattern_cycles_across_barline(self):
        track = generate_track(meter="4/4", bpm=120, bars=3,
                               pattern="(2 1 1 1 1 1 1 1)")
        self.assertEqual(len(track.events), 12)
        self.assertEqual([click.level for click in track.events],
                         [2, 1, 1, 1, 1, 1, 1, 1, 2, 1, 1, 1])
        self.assertEqual(track.events[0].note, 81)
        self.assertEqual(track.events[1].note, 76)
        self.assertAlmostEqual(track.duration_seconds, 6)

    def test_default_accents_each_bar(self):
        track = generate_track(meter="3/4", bpm=60, bars=2)
        self.assertEqual([c.level for c in track.events], [2, 1, 1, 2, 1, 1])

    def test_seconds_and_fractional_bars(self):
        a = generate_track(meter="4/4", bpm=120, bars="3/2")
        b = generate_track(meter="4/4", bpm=120, seconds=3)
        self.assertEqual(len(a.events), 6)
        self.assertEqual(len(a.events), len(b.events))
        self.assertEqual([c.time for c in a.events], [c.time for c in b.events])
        self.assertAlmostEqual(a.duration_seconds, b.duration_seconds)
        c = generate_track(meter="4/4", bpm=60, seconds=1.4)
        self.assertEqual([round(e.time, 2) for e in c.events], [0., 1.])

    def test_compound_meter_unit(self):
        eighths = generate_track(meter="6/8", bpm=60, bars=1)
        dotted = generate_track(meter="6/8", bpm=60, tempo_unit="3/8", bars=1)
        self.assertEqual(len(eighths.events), 6)
        self.assertAlmostEqual(eighths.duration_seconds, 3.)
        self.assertAlmostEqual(dotted.duration_seconds, 2.)
        self.assertAlmostEqual(dotted.events[1].time, 1 / 3)

    def test_custom_5_levels(self):
        track = generate_track(meter="4/4", bpm=100, bars=1,
                               pitches=(60, 64, 68, 72, 76),
                               velocities=(20, 40, 60, 90, 120),
                               pattern=(4, 3, 2, 0))
        self.assertEqual([(c.note, c.velocity) for c in track.events],
                         [(76, 120), (72, 90), (68, 60), (60, 20)])

    def test_invalid_inputs(self):
        bad_cases = [
            dict(meter="4/4", bpm=120, bars=1, seconds=2),
            dict(meter="4/4", bpm=120),
            dict(meter="3/5", bpm=120, bars=1),
            dict(meter="4/4", bpm=-20, bars=1),
            dict(meter="4/4", bpm=120, bars=0),
            dict(meter="4/4", bpm=120, seconds=float("nan")),
            dict(meter="4/4", bpm=120, bars=1, pattern=(4, 1)),
            dict(meter="4/4", bpm=120, bars=1, pattern=(-1, 1)),
            dict(meter="4/4", bpm=120, bars=1, tempo_unit="0/4"),
            dict(meter="4/4", bpm=120, bars=1, pitches=(60, 64, 67),
                 velocities=(90, 70, 100)),
        ]
        for kwargs in bad_cases:
            with self.subTest(kwargs=kwargs), self.assertRaises(ValueError):
                generate_track(**kwargs)
        self.assertEqual(parse_int_list("[3, 2, 1, 0]"), (3, 2, 1, 0))


class ExportTests(unittest.TestCase):
    def test_midi_timing_velocity_pitch_and_timesignature(self):
        track = generate_track(meter="4/4", bpm=120, bars=2,
                               pattern="2 1 1 1 1 1 1 1")
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / "test.mid"
            write_midi(path, track)
            messages = midi_messages(path.read_bytes())
        notes = [m for m in messages if m[1] == 0x90]
        self.assertEqual([n[0] for n in notes], [960 * i for i in range(8)])
        self.assertEqual(notes[0][2:], (81, 101))
        self.assertEqual(notes[1][2:], (76, 76))
        self.assertEqual(messages[-1], (7680, "meta", 0x2F, b""))
        self.assertIn((0, "meta", 0x51, b"\x07\xa1\x20"), messages)
        self.assertIn((0, "meta", 0x58, bytes((4, 2, 24, 8))), messages)
        self.assertIn((0, 0xC0, 115, None), messages)

    def test_midi_dotted_quarter(self):
        track = generate_track(meter="6/8", bpm=90, tempo_unit="3/8", bars=1)
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / "test.mid"
            write_midi(path, track)
            messages = midi_messages(path.read_bytes())
        self.assertEqual([m[0] for m in messages if m[1] == 0x90],
                         [480 * i for i in range(6)])
        tempo = next(m[3] for m in messages if m[1:3] == ("meta", 0x51))
        self.assertEqual(int.from_bytes(tempo, "big"), 444444)
        self.assertIn((0, "meta", 0x58, bytes((6, 3, 12, 8))), messages)
        self.assertEqual(messages[-1][0], 2880)

    def test_wav_length_and_accents(self):
        levels = []
        with tempfile.TemporaryDirectory() as directory:
            for level in range(4):
                track = generate_track(meter="4/4", bpm=60, bars=Fraction(1, 4),
                                       pattern=(level,))
                path = Path(directory) / f"level{level}.wav"
                write_wav(path, track, sample_rate=22050)
                with wave.open(str(path)) as file:
                    self.assertEqual(file.getframerate(), 22050)
                    self.assertEqual(file.getnframes(), 22050)
                    self.assertEqual(file.getnchannels(), 1)
                    self.assertEqual(file.getsampwidth(), 2)
                    pcm = array.array("h")
                    pcm.frombytes(file.readframes(file.getnframes()))
                    if sys.byteorder != "little":
                        pcm.byteswap()
                    rms = math.sqrt(sum(x * x for x in pcm[:3000]) / 3000)
                    levels.append(rms)
        self.assertEqual(sorted(levels), levels)
        self.assertGreater(levels[3], levels[0] * 1.5)

    def test_wav_seconds_length_and_silence_tail(self):
        track = generate_track(meter="4/4", bpm=120, seconds=2.125)
        with tempfile.TemporaryDirectory() as directory:
            path = Path(directory) / "test.wav"
            write_wav(path, track)
            with wave.open(str(path)) as file:
                self.assertEqual(file.getnframes(), round(2.125 * 44100))
                file.setpos(file.getnframes() - 1000)
                self.assertEqual(set(file.readframes(1000)), {0})

    def test_cli_both_formats(self):
        with tempfile.TemporaryDirectory() as directory:
            base = Path(directory) / "out" / "two-bars"
            result = subprocess.run(
                [sys.executable, "-m", "metronome", "--meter", "4/4",
                 "--bpm", "120", "--bars", "2", "--pattern", "(2 1 1 1 1 1 1 1)",
                 "--output", str(base)], capture_output=True, text=True,
            )
            self.assertEqual(result.returncode, 0, result.stderr)
            self.assertTrue(base.with_suffix(".mid").exists())
            self.assertTrue(base.with_suffix(".wav").exists())


if __name__ == "__main__":
    unittest.main()
